{
  "version": "questions-v1",
  "about": "Every Jev question set put to `POST /v1/systemone`, in one file. The Flock's sets: `flock_step`, read by factory/flock/step_reading.mjs once per green story step; `flock_resolve`, read by factory/flock/engine.mjs at a merge conflict an agent resolves; and `flock_release`, read by factory/flock/engine.mjs at a task given back; their modes live in factory/policy.json's `flock.jev_step`, `flock.jev_resolve` and `flock.jev_release`. The authoring sets, `authoring_…`: each says when it is asked (`when`), who reads it (`reader`), how to turn it off (`rollback`), the keys its reader sends (`state`), where it came from (`provenance`) and whether its readings are calibrated. Each set names its reader and its rollback (map #1131 rule 3). A question is literal: it names no policy word, and nothing here decides anything. A Jev `null` routes that reading to the set's stated rollback, never to a guess. A reworded question is a different question: its readings mean something else.",
  "sets": {
    "flock_step": {
      "when": "At a ready settle, once per story, at its last green step (#1369)",
      "reader": "factory/flock/step_reading.mjs",
      "rollback": "factory/policy.json flock.jev_step.mode = off",
      "state": [
        "story",
        "step",
        "did",
        "before",
        "after",
        "changes",
        "screen_text"
      ],
      "provenance": "state-probe runner spec 2026-09-27 §7; TypeSafe citation-check recipe (supports / contradicts / says nothing)",
      "calibrated": false,
      "questions": {
        "delivered": {
          "type": "choice",
          "instructions": {
            "question": "After the user did `did`, do `after` and `screen_text` show that `story` came true?",
            "context": "`story` is the sentence the operator signed. `before` and `after` are the app's store as [tables, values] before the story's first step and after its last; row ids are numbered by creation order. When the store is too big to send whole, `changes` stands in for `before` and `after`: one {table, row, before, after} per row that differs, a missing row null. `screen_text` is the page's visible text after the last step. `did` is everything the user clicked or typed, every step of the story in order."
          },
          "criteria": {
            "supports": "The store or the screen after the step shows the outcome the sentence describes",
            "contradicts": "The store or the screen shows something the sentence rules out",
            "says_nothing": "The evidence neither shows nor rules out the sentence's outcome"
          }
        }
      }
    },
    "flock_resolve": {
      "when": "When an agent resolves a merge conflict in a file of its copy, once per resolve",
      "reader": "factory/flock/engine.mjs",
      "rollback": "factory/policy.json flock.jev_resolve.mode = off",
      "state": [
        "path",
        "conflicts",
        "tasks"
      ],
      "provenance": "factory review reading 2026-09-29 (Jev candidate 1); operator pick 2026-09-29",
      "calibrated": false,
      "questions": {
        "already_joined": {
          "type": "choice",
          "instructions": {
            "question": "In `annotated`, do the left and right sides of each conflict already fit together as the merged text shows them, so the file needs no edit?",
            "context": "`conflicts` holds each conflict of the merged file as a `<<<<<<<` / `=======` / `>>>>>>>` section with its left and right sides and a few unmarked lines around it. `path` is the file. `tasks` are the tasks that touch it, each with its `title` and its `claim`, what that side meant."
          },
          "criteria": {
            "no_edit_needed": "Both sides say things that stand together as merged",
            "needs_edit": "One side's meaning is lost, or the text does not read as one file, until someone edits it",
            "contradictory": "The two sides want opposite things, and one must be chosen"
          }
        }
      }
    },
    "flock_release": {
      "when": "When an agent gives its task back to the board, once per release",
      "reader": "factory/flock/engine.mjs",
      "rollback": "factory/policy.json flock.jev_release.mode = off",
      "state": [
        "task",
        "title",
        "files",
        "claim",
        "facts",
        "reason",
        "earlier_reasons",
        "depends_on"
      ],
      "provenance": "factory review reading 2026-09-29 (Jev candidate 2); operator pick 2026-09-29",
      "calibrated": false,
      "questions": {
        "blocker": {
          "type": "choice",
          "instructions": {
            "question": "Given `reason`, what stands between this task and its facts passing?",
            "context": "`task` and `title` name the task. `files` are the files it may change. `claim` is what the task must prove, and `facts` are the commands that decide it. `reason` is what the agent said when it gave the task back; `earlier_reasons` are its last give-backs before this one. `depends_on` are the tasks it depends on."
          },
          "criteria": {
            "fixable": "Another attempt at `files` could make them pass",
            "waiting_on_peer": "They need work another task in `depends_on` or elsewhere has not published yet",
            "plan_defect": "No change to `files` can make them pass as the plan states them"
          }
        }
      }
    },
    "authoring_ambiguity": {
      "when": "At jev_checks.ts --stage understanding and --stage bundle",
      "reader": "skills/ultrawrite/stories/jev_checks.ts",
      "rollback": "skills/ultrawrite/stories/policy.json flag_at: flags off, the author's own read decides",
      "state": [
        "ask",
        "sentences"
      ],
      "provenance": "moved from skills/ultrawrite/stories/questions.json (authoring-questions-v2), 2026-09-29",
      "calibrated": false,
      "questions": {
        "two_apps": {
          "type": "noul",
          "instructions": {
            "question": "Could `sentences[i]` describe two apps that behave differently in a way the person who wrote `ask` would care about?",
            "context": "`ask` is everything the person wrote; `sentences` are its sentences, in order."
          },
          "criteria": {
            "true": "Two reasonable readings lead to apps that act differently",
            "false": "Every reasonable reading leads to the same behaviour"
          }
        }
      }
    },
    "authoring_coherence": {
      "when": "At jev_checks.ts --stage bundle; one_need also at --stage map",
      "reader": "skills/ultrawrite/stories/jev_checks.ts",
      "rollback": "skills/ultrawrite/stories/policy.json flag_at: flags off, the author's own read decides",
      "state": [
        "piece"
      ],
      "provenance": "moved from skills/ultrawrite/stories/questions.json (authoring-questions-v2), 2026-09-29",
      "calibrated": false,
      "questions": {
        "one_need": {
          "type": "noul",
          "instructions": "Does `piece.purpose` state one need that a single short sentence covers?",
          "criteria": {
            "true": "One need",
            "false": "Two or more needs joined together"
          }
        },
        "same_people": {
          "type": "noul",
          "instructions": "Do all of `piece.actions` serve the same people for the same reason?",
          "criteria": {
            "true": "The same people, the same reason",
            "false": "Some actions serve different people or a different reason"
          }
        }
      }
    },
    "authoring_near_miss": {
      "when": "At jev_checks.ts --stage bundle",
      "reader": "skills/ultrawrite/stories/jev_checks.ts",
      "rollback": "skills/ultrawrite/stories/policy.json flag_at: flags off, the author's own read decides",
      "state": [
        "piece",
        "story",
        "story_steps",
        "near_miss"
      ],
      "provenance": "moved from skills/ultrawrite/stories/questions.json (authoring-questions-v2), 2026-09-29",
      "calibrated": false,
      "questions": {
        "story_passes_near_miss": {
          "type": "noul",
          "instructions": {
            "question": "If the app behaved like `near_miss` instead, would `story` still come out exactly as it is written?",
            "context": "`story` is the main story that should prove `piece` works; `story_steps` are its steps, each an action called (`tool`, `args`) and what the person then sees (`see`). `near_miss` is a look-alike that must fail it."
          },
          "criteria": {
            "true": "The story cannot tell the two apart",
            "false": "The story would come out differently for the look-alike"
          }
        }
      }
    },
    "authoring_content_branch": {
      "when": "At jev_checks.ts --stage bundle",
      "reader": "skills/ultrawrite/stories/jev_checks.ts",
      "rollback": "skills/ultrawrite/stories/policy.json flag_at: flags off, the author's own read decides",
      "state": [
        "store_module",
        "actions"
      ],
      "provenance": "moved from skills/ultrawrite/stories/questions.json (authoring-questions-v2), 2026-09-29",
      "calibrated": false,
      "questions": {
        "branches_on_text": {
          "type": "noul",
          "instructions": {
            "question": "Does the action named `actions[i].name` in `store_module` behave differently depending on the wording of text the person typed, beyond whether it is empty?",
            "context": "`store_module` is the app's whole store code; `actions` are its actions, each with the piece it belongs to and its description. An action that treats a title ending in '?' differently is the kind of thing asked about."
          },
          "criteria": {
            "true": "It inspects the words and changes behaviour",
            "false": "It stores or compares the text without reading its wording"
          }
        }
      }
    },
    "authoring_redundancy": {
      "when": "At jev_checks.ts --stage bundle",
      "reader": "skills/ultrawrite/stories/jev_checks.ts",
      "rollback": "skills/ultrawrite/stories/policy.json flag_at: flags off, the author's own read decides",
      "state": [
        "pieces"
      ],
      "provenance": "moved from skills/ultrawrite/stories/questions.json (authoring-questions-v2), 2026-09-29",
      "calibrated": false,
      "questions": {
        "same_need": {
          "type": "noul",
          "instructions": "Do `pieces[i].purpose` and `pieces[j].purpose` describe the same need?",
          "criteria": {
            "true": "The same need, twice",
            "false": "Different needs"
          }
        }
      }
    },
    "authoring_surprise": {
      "when": "At jev_checks.ts --stage understanding",
      "reader": "skills/ultrawrite/stories/jev_checks.ts",
      "rollback": "skills/ultrawrite/stories/policy.json flag_at: flags off, the author's own read decides",
      "state": [
        "ask",
        "assumption"
      ],
      "provenance": "moved from skills/ultrawrite/stories/questions.json (authoring-questions-v2), 2026-09-29",
      "calibrated": false,
      "questions": {
        "assumption_surprises": {
          "type": "noul",
          "instructions": {
            "question": "Would the person who wrote `ask` be surprised to learn that the app `assumption`?",
            "context": "`ask` is everything the person wrote; `assumption` is something the author assumed the app does, about what it does, who uses it or how it looks."
          },
          "criteria": {
            "true": "They would be surprised; it goes beyond or against what they asked",
            "false": "It is what they would expect from what they asked"
          }
        }
      }
    },
    "authoring_map": {
      "when": "At jev_checks.ts --stage map",
      "reader": "skills/ultrawrite/stories/jev_checks.ts",
      "rollback": "skills/ultrawrite/stories/policy.json flag_at: flags off, the author's own read decides",
      "state": [
        "summary",
        "audience",
        "piece",
        "other_purposes"
      ],
      "provenance": "moved from skills/ultrawrite/stories/questions.json (authoring-questions-v2), 2026-09-29",
      "calibrated": false,
      "questions": {
        "essential": {
          "type": "noul",
          "instructions": {
            "question": "Is `piece.purpose` part of the core of what `summary` describes, rather than an extra?",
            "context": "`summary` says what the product is, why it exists and how it is used. `piece.purpose` is one thing the product could do; `other_purposes` are the other things it could do; `audience` are the people who use it."
          },
          "criteria": {
            "true": "Core",
            "false": "An extra"
          }
        },
        "serves_summary": {
          "type": "noul",
          "instructions": {
            "question": "Does `piece.purpose` serve what `summary` says the product is for?",
            "context": "`summary` says what the product is, why it exists and how it is used. `other_purposes` are the other things the product could do."
          },
          "criteria": {
            "true": "It serves that purpose",
            "false": "It serves something else"
          }
        }
      }
    },
    "authoring_decompose": {
